typedef float time_value_t;

class ScoringManager
{
public:
    char pad[0x10fc];
    int score;
    int GetScore() { return score; }
};

class kellyslater_controller
{
public:
    char pad[0x10fc];
    ScoringManager my_scoreManager;
    ScoringManager &get_my_scoreManager() { return my_scoreManager; }
};

class world_dynamics_system
{
public:
    char pad[0xf8];
    kellyslater_controller *ks_controller[2];
    kellyslater_controller *get_ks_controller(int n) { return ks_controller[n]; }
};

class game
{
public:
    char pad0[0x74];
    int game_mode;
    char pad1[0x44];
    int active_player;
    int get_game_mode() { return game_mode; }
    int get_active_player() { return active_player; }
};

class IGOIconManager
{
public:
    char pad[0xb5c];
    int iconCounter;
    int IconsCleared() { return iconCounter; }
};

class HighScoreFrontEnd
{
public:
    static bool IsNewHighScore(const int score, const int icons);
};

class PauseMenuSystem
{
public:
    enum { HighScoreMenu = 16 };
    char pad0[0x7c];
    int active;
    char pad1[0x10];
    int draw;
    void startDraw(int menu);
    void UpdateButtonDown();
};

class FEManager
{
public:
    char pad[4];
    PauseMenuSystem *pms;
};

class IGOFrontEnd
{
public:
    enum RUNSTATE { RUNSTATE_PHOTOS = 5 };
    char pad0[0xbc];
    FEManager *manager;
    char pad1[0x68];
    RUNSTATE runState;
    char pad2[0xcc];
    struct HIGHSCORE { int waitingOnMenu; } highScore;
    char pad3[0x27c];
    IGOIconManager *iconManager;
    char pad4[4];
    void *tutorialManager;

    void ShowAccompBackground(bool enabled, int h = 0, int v = 0);
    void UpdateStatePhotos(time_value_t time_inc);
    void UpdateStateHighScore(time_value_t time_inc);
};

extern world_dynamics_system *g_world_ptr;
extern game *g_game_ptr;

enum
{
    GAME_MODE_CAREER = 0,
    GAME_MODE_FREESURF_HIGHSCORE = 2,
    GAME_MODE_FREESURF_ICON = 3
};

void IGOFrontEnd::UpdateStateHighScore(time_value_t time_inc)
{
	int		score = 0;
	int		icons = 0;
	bool	advanceState = false;
	bool	popup = true;

	if (highScore.waitingOnMenu == -1)
	{
		score = g_world_ptr->get_ks_controller(g_game_ptr->get_active_player())->get_my_scoreManager().GetScore();
		if (iconManager)
			icons = iconManager->IconsCleared();

		// Only popup menu in highscore mode, or in career mode but not tutorial. (dc 06/10/02)
		if (HighScoreFrontEnd::IsNewHighScore(score, icons))
		{
			popup = (g_game_ptr->get_game_mode() == GAME_MODE_FREESURF_HIGHSCORE ||
				g_game_ptr->get_game_mode() == GAME_MODE_FREESURF_ICON ||
				(g_game_ptr->get_game_mode() == GAME_MODE_CAREER && !tutorialManager));
		}
		else
			popup = false;
	}

	if (popup)
	{
		// First frame: popup high score menu.
		if ((manager->pms->active != PauseMenuSystem::HighScoreMenu || !manager->pms->draw) &&
			highScore.waitingOnMenu == -1)
		{
			ShowAccompBackground(true);
			manager->pms->startDraw(PauseMenuSystem::HighScoreMenu);
			manager->pms->UpdateButtonDown();
			highScore.waitingOnMenu = manager->pms->active;
		}
		// Wait for high score menu to finish.
		else if (highScore.waitingOnMenu != -1 && !manager->pms->draw)
		{
			advanceState = true;
		}
	}
	else
	{
		advanceState = true;
	}

	// High score menu finished, proceed with normal end run states.
	if (advanceState)
	{
		ShowAccompBackground(false);
		highScore.waitingOnMenu = -1;
		runState = RUNSTATE_PHOTOS;
		UpdateStatePhotos(time_inc);
	}
}
